function trainersByLocation(){
  const all=state.data.trainers||[],stages=state.data.trainer_journey?.stages||[];
  const groups=stages.map(stage=>({...stage,trainers:all.filter(t=>t.journey?.stage_id===stage.id).sort((a,b)=>a.journey.order-b.journey.order)})).filter(stage=>stage.trainers.length);
  const other=all.filter(t=>!t.journey);
  if(other.length)groups.push({id:'other',name:{en:'Other battles and variants',es:'Otros combates y variantes'},trainers:other});
  return `<h1>${L().trainers}</h1><p class="mode-note">${esc(text(state.data.game_modes?.[state.gameMode]?.description))}</p><p class="intro">${state.lang==='es'?'Sigue el recorrido recomendado y abre cada equipo para preparar el combate. Los rematches tienen su propio filtro; las rutas opcionales y Kanto permiten elegir camino.':'Follow the recommended journey and open each team to prepare. Rematches have their own filter; optional routes and Kanto allow different paths.'}</p>
    <div class="filters"><select id="trainer-kind" aria-label="${state.lang==='es'?'Tipo de combate':'Battle kind'}"><option value="first_visit">${state.lang==='es'?'Primera visita':'First visit'}</option><option value="rematch">${state.lang==='es'?'Rematches':'Rematches'}</option><option value="other">${state.lang==='es'?'Orden por confirmar':'Order unconfirmed'}</option><option value="">${state.lang==='es'?'Todos los combates':'All battles'}</option></select>
    <select id="trainer-location" aria-label="${state.lang==='es'?'Tramo de aventura':'Journey stage'}"><option value="">${state.lang==='es'?'Todo el recorrido':'Whole journey'}</option>${groups.map(stage=>`<option value="${stage.id}">${esc(text(stage.name))}</option>`).join('')}</select>
    <input id="trainer-filter" placeholder="${L().name}" aria-label="${L().name}"><input id="trainer-pokemon" placeholder="Pokémon" aria-label="Pokémon"><input id="trainer-move" placeholder="${state.lang==='es'?'Movimiento':'Move'}" aria-label="${state.lang==='es'?'Movimiento':'Move'}"></div><p id="trainer-result-count" class="muted" role="status"></p>
    <div class="journey-layout"><nav class="journey-nav" aria-label="${state.lang==='es'?'Recorrido':'Journey'}">${groups.map(stage=>`<button data-jump="journey-${stage.id}">${esc(text(stage.name))}</button>`).join('')}</nav>
    <div id="trainer-grid">${groups.map(stage=>`<section id="journey-${stage.id}" class="location-group journey-stage" data-location="${stage.id}"><div class="journey-heading"><h2>${esc(text(stage.name))}</h2><small>${stage.trainers.length} ${L().trainers.toLowerCase()}</small></div><div class="trainer-grid">${stage.trainers.map(trainerCard).join('')}</div></section>`).join('')}</div></div>`;
}
function wireTrainerJourney(){
  const apply=()=>{
    const query=['search','trainer-filter','trainer-pokemon','trainer-move'].map(id=>($(id)?.value||'').toLowerCase()).filter(Boolean),kind=$('trainer-kind').value,place=$('trainer-location').value;
    document.querySelectorAll('.trainer-card').forEach(card=>{card.hidden=query.some(word=>!card.dataset.search.includes(word))||!!(kind&&card.dataset.kind!==kind)||!!(place&&card.closest('.journey-stage').dataset.location!==place)});
    document.querySelectorAll('.journey-stage').forEach(stage=>{stage.hidden=[...stage.querySelectorAll('.trainer-card')].every(card=>card.hidden);document.querySelector(`[data-jump="${stage.id}"]`).hidden=stage.hidden});
    $('trainer-result-count').textContent=`${document.querySelectorAll('.trainer-card:not([hidden])').length} ${L().trainers.toLowerCase()}`;
  };
  ['search','trainer-filter','trainer-pokemon','trainer-move'].forEach(id=>{if($(id)){$(id).oninput=apply;$(id).onchange=null}});
  ['trainer-kind','trainer-location'].forEach(id=>$(id).onchange=apply);
  document.querySelectorAll('.trainer-roster').forEach(details=>details.ontoggle=()=>{if(details.open&&!details.dataset.loaded){details.querySelector('.team').innerHTML=trainerTeam(state.data.trainers.find(t=>String(t.id)===details.dataset.trainerId));details.dataset.loaded='true'}});
  document.querySelectorAll('[data-jump]').forEach(button=>button.onclick=()=>document.getElementById(button.dataset.jump).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}));
  apply();
}
function trainers(){const d=state.data,species=Object.fromEntries((d.species||[]).map(p=>[p.id,p.name]));return `<h1>${L().trainers}</h1><div class="filters"><input id="trainer-filter" placeholder="${L().name}"><input id="trainer-pokemon" placeholder="Pokémon"><input id="trainer-move" placeholder="Move"></div><div id="trainer-grid" class="trainer-grid">${(d.trainers||[]).map(t=>`<article class="trainer-card" data-search="${esc(trainerSearch(t))}"><h2>${esc(text(t.name))}</h2><small>${L().id} ${t.id}</small><div class="team">${(t.members||[]).map(m=>`<div class="team-member">${sprite(m.species_id,'mini')}<span><strong>${esc(nameOf(species,m.species_id))}</strong> · ${L().level} ${m.level}<br><small>${L().held}: ${m.item_id?romName(itemName(m.item_id)):'—'}<br>${(m.move_ids||[]).filter(Boolean).map(id=>`<a href="#/moves/${id}">${esc(nameOf(moves(),id))}</a>`).join(' · ')||'—'}<br><em>${moveResolution(m)}</em></small></span></div>`).join('')}</div></article>`).join('')}</div>`}
