function movesList(){const groups={};Object.entries(moves()).forEach(([id,m])=>(groups[m.type_id]??=[]).push([id,m]));const tm=(state.data.tmhm||[]).filter(x=>x.kind==='tm'),hm=(state.data.tmhm||[]).filter(x=>x.kind==='hm');return `<h1>${L().moves}</h1><div class="filters"><input id="move-filter" placeholder="${L().name}"><select id="move-type"><option value="">${L().type}</option>${Object.entries(types()).map(([id,n])=>`<option value="${id}">${esc(text(n))}</option>`).join('')}</select><select id="move-class"><option value="">${state.lang==='es'?'Clase':'Class'}</option><option value="0">${state.lang==='es'?'Físico':'Physical'}</option><option value="1">${state.lang==='es'?'Especial':'Special'}</option><option value="2">${state.lang==='es'?'Estado':'Status'}</select></div>${Object.entries(groups).map(([typeId,list])=>`<section class="move-group"><h2>${esc(nameOf(types(),typeId))}</h2><div class="move-grid">${list.map(([id,m])=>`<a class="move-card" data-type="${m.type_id}" data-class="${m.category}" data-search="${esc(text(m.name)).toLowerCase()}" href="#/moves/${id}"><h3>${esc(text(m.name))}</h3>${typeBadge(m.type_id)}<span class="tag">${esc(moveCategory(m))}</span><p>${L().power} ${m.power??'—'} · ${L().accuracy} ${m.accuracy||'—'} · ${L().pp} ${m.pp??'—'}</p><progress class="move-power" max="250" value="${Math.min(250,m.power||0)}"></progress></a>`).join('')}</div></section>`).join('')}<section class="move-group"><h2>${state.lang==='es'?'MT / MO':'TM / HM'}</h2><p>${tm.length} TM · ${hm.length} HM</p></section>`}
function itemsList(){const d=state.data;return `<h1>${L().items}</h1><input id="item-filter" placeholder="${L().name}"><div class="filters"><select id="item-category"><option value="">${state.lang==='es'?'Categoría':'Category'}</option>${[...new Set(Object.values(d.items||{}).map(x=>text(x.category)||x.category_id).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="item-grid" class="item-list">${Object.entries(d.items||{}).map(([id,item])=>`<article class="item-row" data-search="${esc(`${romNameSearch(item.name)} ${acquisitionSearch(item)}`).toLowerCase()}" data-category="${esc(text(item.category)||item.category_id||'')}"><details class="item-row__details"><summary><span class="item-row__heading">${item.sprite?`<img class="sprite mini" src="${esc(item.sprite)}" alt="">`:''}<span><strong>${romName(item.name)}</strong>${itemIconNote(item)}</span><span class="item-row__category">${esc(text(item.category)||item.category_id||'')}</span><span class="item-row__toggle">${state.lang==='es'?'Ver detalles':'View details'}</span></span></summary><div class="item-row__body"><a class="item-row__link" href="#/items/${id}">${state.lang==='es'?'Abrir ficha':'Open item page'}: ${romName(item.name)}</a><p>${esc(text(item.description))}</p><ul class="acquisition">${acquisition(item)}</ul></div></details></article>`).join('')}</div>`}
function acquisitionSearch(item){return (item.acquisition||[]).map(a=>`${romNameSearch(a.location?.name||a.location)} ${text(a.method)}`).join(' ')}
function item(id){const item=state.data.items?.[id];if(!item)return missing();return `<p><a href="#/items">← ${L().back}</a></p><article class="card">${item.sprite?`<img class="sprite" src="${esc(item.sprite)}" alt="">`:''}<h1>${romName(item.name)} ${itemIconNote(item)}</h1><p>${esc(text(item.description))}</p><small>${L().id} ${item.nds_id||id}</small><ul class="acquisition">${acquisition(item,true)}</ul></article>`}
function machines(){const d=state.data,rows=d.tmhm||[];return `<h1>${state.lang==='es'?'MT / MO':'TMs / HMs'}</h1><div class="filters"><input id="machine-filter" placeholder="${L().name}"><select id="machine-kind"><option value="">${state.lang==='es'?'Todas':'All'}</option><option value="tm">${state.lang==='es'?'MT':'TM'}</option><option value="hm">${state.lang==='es'?'MO':'HM'}</option></select><select id="machine-type"><option value="">${L().type}</option>${Object.entries(types()).map(([id,n])=>`<option value="${id}">${esc(text(n))}</option>`).join('')}</select></div><div id="machine-grid" class="machine-list">${rows.map(r=>{const item=d.items?.[r.item_id]||{},m=moves()[r.move_id]||{};return `<article class="machine-row type-${m.type_id||0}" data-kind="${r.kind}" data-type="${m.type_id??''}" data-search="${esc(`${romNameSearch(item.name)} ${text(m.name)} ${acquisitionSearch(item)}`).toLowerCase()}"><details class="machine-row__details"><summary><span class="machine-row__heading"><strong>${state.lang==='es'?(r.kind==='tm'?'MT':'MO'):r.kind.toUpperCase()}${r.number?` ${r.number}`:''}: ${esc(text(m.name))}</strong>${typeBadge(m.type_id)}<span class="machine-row__item">${romName(item.name)}</span><span class="machine-row__toggle">${state.lang==='es'?'Ver obtención':'View acquisition'}</span></span></summary><div class="machine-row__body"><a class="item-row__link" href="#/items/${r.item_id}">${state.lang==='es'?'Abrir ficha del objeto':'Open item page'}: ${romName(item.name)}</a><ul class="acquisition">${acquisition(item)}</ul></div></details></article>`}).join('')}</div>`}
function evolutionFamilies(){
  const species=state.data.species||[],byId=new Map(species.map(p=>[String(p.id),p])),adjacency=new Map(species.map(p=>[String(p.id),new Set()])),edges=[];
  species.forEach(p=>(p.evolutions||[]).forEach(e=>{const from=String(p.id),to=String(e.target);if(!byId.has(to))return;edges.push({from,to,e});adjacency.get(from).add(to);adjacency.get(to).add(from)}));
  const seen=new Set(),families=[];
  for(const [start,neighbors] of adjacency){if(!neighbors.size||seen.has(start))continue;const ids=new Set(),pending=[start];while(pending.length){const id=pending.pop();if(ids.has(id))continue;ids.add(id);seen.add(id);for(const next of adjacency.get(id))if(!ids.has(next))pending.push(next)}
    const familyEdges=edges.filter(edge=>ids.has(edge.from)&&ids.has(edge.to)).sort((a,b)=>Number(a.from)-Number(b.from)||Number(a.to)-Number(b.to)),incoming=new Set(familyEdges.map(edge=>edge.to));
    const members=[...ids].map(id=>byId.get(id)).sort((a,b)=>Number(a.id)-Number(b.id)),rootCandidates=members.filter(p=>!incoming.has(String(p.id))),roots=rootCandidates.length?rootCandidates:[members[0]];
    families.push({members,roots,edges:familyEdges,byId});
  }
  return families.sort((a,b)=>Number((a.roots[0]||a.members[0]).id)-Number((b.roots[0]||b.members[0]).id));
}
function evolutionSearchNames(value){return typeof value==='object'&&value?Object.values(value).join(' '):String(value||'')}
function evolutions(){
  const families=evolutionFamilies(),es=state.lang==='es';
  return `<section class="evolution-page"><h1>${L().evolutions}</h1><p class="intro">${es?'Cada ficha reúne una familia completa y las condiciones de cada cambio, según los datos de esta ROM.':'Each card groups a complete family and the condition for every transition, using this ROM’s data.'}</p><div class="filters"><input id="evolution-filter" type="search" placeholder="${es?'Buscar cualquier Pokémon de la familia':'Search any Pokémon in a family'}" aria-label="${es?'Buscar familias evolutivas':'Search evolution families'}"></div><p class="muted" role="status">${families.length} ${es?'familias evolutivas':'evolution families'}</p><div id="evolution-grid" class="evolution-families">${families.map(family=>{const rootNames=family.roots.map(p=>text(p.name)).join(' · '),memberNames=family.members.map(p=>text(p.name)).join(' '),searchNames=family.members.map(p=>evolutionSearchNames(p.name)).join(' '),familyLabel=es?`Familia de ${rootNames}`:`${rootNames} family`;return `<article class="evolution-family" data-search="${esc(`${searchNames} ${memberNames}`).toLowerCase()}"><header class="evolution-family__header"><div><p class="section-kicker">${es?'FAMILIA EVOLUTIVA':'EVOLUTION FAMILY'}</p><h2>${esc(familyLabel)}</h2></div><span class="evolution-family__count">${family.members.length} ${es?'especies':'species'} · ${family.edges.length} ${es?'cambios':'transitions'}</span></header><div class="evolution-family__members" aria-label="${es?'Miembros de la familia':'Family members'}">${family.members.map(p=>`<a class="evolution-member" href="#/pokemon/${p.id}">${sprite(p.id,'mini')}<span>${esc(text(p.name))}</span></a>`).join('')}</div><div class="evolution-family__edges" aria-label="${es?'Métodos de evolución':'Evolution methods'}">${family.edges.map(({from,to,e})=>{const source=family.byId.get(from),target=family.byId.get(to);return `<div class="evolution-edge"><a class="evolution-edge__node" href="#/pokemon/${from}">${sprite(from,'mini')}<span>${esc(text(source.name))}</span></a><span class="evolution-edge__arrow" aria-hidden="true">→</span><a class="evolution-edge__node" href="#/pokemon/${to}">${sprite(to,'mini')}<span>${esc(text(target.name))}</span></a><p class="evolution-edge__condition">${esc(evolutionCondition(e))}</p></div>`}).join('')}</div></article>`}).join('')}</div></section>`
}
function section(key){const g=state.data.guides?.[key];return `<h1>${esc(text(g?.title)||L()[key]||key)}</h1><article class="guide">${g?.body?.[state.lang]||`<p>${L().noData}</p>`}</article>`}
function guidesIndex(){
  const pages=state.data.guides||{},assigned=new Set(['guides']);
  const take=slugs=>{const selected=slugs.filter(slug=>pages[slug]&&!assigned.has(slug));selected.forEach(slug=>assigned.add(slug));return selected};
  const groups=[
    {label:state.lang==='es'?'Empieza aquí':'Start here',slugs:take(['player','faq','web-patcher'])},
    {label:state.lang==='es'?'Jugar y explorar':'Play and explore',slugs:take(['trainer-battles','battle-frontier','mechanics','hm','items','tm-guide','tm-refill','repel-reuse'])},
    {label:state.lang==='es'?'Datos de referencia y fuentes':'Reference data and sources',slugs:take(['evolutions','item-locations','trainer-locations','sources','sources-inventory','drayano-crosscheck','mods-crosscheck','pchal-resources','nature-override-consumers'])},
    {label:state.lang==='es'?'Características y herramientas opcionales':'Features and optional tools',slugs:take(['features','kit','cheats'])},
    {label:state.lang==='es'?'Estado y recursos del proyecto':'Project status and assets',slugs:take(['progress','discrepancy-register','branding-assets','custom-item-art','wiki-ui'])},
    {label:state.lang==='es'?'Estudios de viabilidad y propuestas':'Feasibility studies and proposals',slugs:take([...Object.keys(pages).filter(slug=>slug.includes('feasibility')),'stat-editor','kris'])},
    {label:state.lang==='es'?'Informes de QA y verificación':'QA and verification reports',slugs:take(Object.keys(pages).filter(slug=>slug==='qa'||slug==='cheat-kit-audit'||slug.startsWith('qa-')||slug.endsWith('-qa')||slug.includes('-qa-')||slug.includes('-review')||slug.includes('fix6a')))},
    {label:state.lang==='es'?'Otros registros del proyecto':'Additional project records',slugs:take(Object.keys(pages).filter(slug=>slug!=='guides').sort())}
  ];
  const body=groups.filter(group=>group.slugs.length).map(group=>`<section><h2>${esc(group.label)}</h2><div class="guide-index">${group.slugs.map(slug=>`<a href="#/guide/${slug}"><h3>${esc(text(pages[slug].title))}</h3></a>`).join('')}</div></section>`).join('');
  return `<h1>${esc(text(pages.guides?.title)||L().guides)}</h1><article class="guide">${body||`<p>${L().noData}</p>`}</article>`;
}
function guide(slug){const g=state.data.guides?.[slug];if(!g)return missing();return `<p><a href="#/guides">← ${L().back}</a></p><h1>${esc(text(g.title))}</h1><article class="guide">${g.body?.[state.lang]||`<p>${L().noData}</p>`}</article>`}
function featureComposition(){const es=state.lang==='es',labels=es?{lineage:'Linaje acreditado',patch:'Rutas directas de parche',drayano:'Drayano',drayanoSub:'Sacred Gold / Storm Silver 1.05',plus:'Sacred Gold Plus',plusSub:'Versión 1.2.3',input:'Pokémon HeartGold USA',inputSub:'Entrada limpia fijada',alpha1:'Ultimate Gold · Alfa 1',alpha1Sub:'Pruebas parciales',alpha2:'Ultimate Gold · Alfa 2',alpha2Sub:'Experimental'}:{lineage:'Credited upstream lineage',patch:'Direct patch routes',drayano:'Drayano',drayanoSub:'Sacred Gold / Storm Silver 1.05',plus:'Sacred Gold Plus',plusSub:'Version 1.2.3',input:'Pokémon HeartGold USA',inputSub:'Pinned clean input',alpha1:'Ultimate Gold · Alpha 1',alpha1Sub:'Tested partial',alpha2:'Ultimate Gold · Alpha 2',alpha2Sub:'Experimental'};const source=es?'flowchart LR\n  subgraph L[Linaje upstream]\n    D[Drayano · Sacred Gold 1.05] --> P[Sacred Gold Plus 1.2.3]\n  end\n  subgraph R[Parche desde HeartGold limpio]\n    H[HeartGold USA limpia] --> A1[Ultimate Gold Alfa 1]\n    H --> A2[Ultimate Gold Alfa 2]\n  end':'flowchart LR\n  subgraph L[Upstream lineage]\n    D[Drayano · Sacred Gold 1.05] --> P[Sacred Gold Plus 1.2.3]\n  end\n  subgraph R[Patch from clean HeartGold]\n    H[Clean HeartGold USA] --> A1[Ultimate Gold Alpha 1]\n    H --> A2[Ultimate Gold Alpha 2]\n  end';return `<figure class="feature-map" aria-labelledby="feature-map-caption"><figcaption id="feature-map-caption"><span>${es?'Linaje y ruta de los parches':'Lineage and patch route'}</span><span class="feature-map__scroll-hint">${es?'Desliza para ver el diagrama completo':'Scroll to see the full diagram'} <span aria-hidden="true">↔</span></span></figcaption><div class="feature-map__viewport" role="region" tabindex="0" aria-label="${es?'Diagrama desplazable de composición':'Scrollable build composition diagram'}"><svg viewBox="0 0 900 300" role="img" aria-labelledby="feature-map-title feature-map-description"><title id="feature-map-title">${es?'Composición de Ultimate Gold':'Ultimate Gold composition'}</title><desc id="feature-map-description">${es?'El linaje upstream conecta Sacred Gold de Drayano con Sacred Gold Plus. Por separado, Alfa 1 y Alfa 2 se parchean directamente desde la misma HeartGold USA limpia.':'The upstream lineage connects Drayano’s Sacred Gold to Sacred Gold Plus. Separately, Alpha 1 and Alpha 2 are patched directly from the same clean HeartGold USA input.'}</desc><defs><marker id="feature-map-arrow" markerWidth="9" markerHeight="9" refX="7" refY="4.5" orient="auto"><path d="M0,0 L9,4.5 L0,9 z" class="feature-map__arrowhead"/></marker></defs><text x="30" y="28" class="feature-map__lane">${labels.lineage}</text><rect x="30" y="44" width="305" height="72" rx="12" class="feature-map__node"/><text x="52" y="73" class="feature-map__label">${labels.drayano}</text><text x="52" y="96" class="feature-map__meta">${labels.drayanoSub}</text><path d="M335 80 H410" class="feature-map__connector" marker-end="url(#feature-map-arrow)"/><rect x="424" y="44" width="330" height="72" rx="12" class="feature-map__node feature-map__node--heritage"/><text x="446" y="73" class="feature-map__label">${labels.plus}</text><text x="446" y="96" class="feature-map__meta">${labels.plusSub}</text><text x="30" y="151" class="feature-map__lane">${labels.patch}</text><rect x="30" y="168" width="305" height="94" rx="12" class="feature-map__node feature-map__node--source"/><text x="52" y="205" class="feature-map__label">${labels.input}</text><text x="52" y="230" class="feature-map__meta">${labels.inputSub}</text><path d="M335 215 H390 V190 H424" class="feature-map__connector" marker-end="url(#feature-map-arrow)"/><path d="M390 215 V259 H424" class="feature-map__connector" marker-end="url(#feature-map-arrow)"/><rect x="438" y="166" width="316" height="52" rx="10" class="feature-map__node"/><text x="456" y="188" class="feature-map__label">${labels.alpha1}</text><text x="456" y="207" class="feature-map__meta">${labels.alpha1Sub}</text><rect x="438" y="233" width="316" height="52" rx="10" class="feature-map__node feature-map__node--experimental"/><text x="456" y="255" class="feature-map__label">${labels.alpha2}</text><text x="456" y="274" class="feature-map__meta">${labels.alpha2Sub}</text></svg></div><p class="feature-map__note">${es?'El linaje indica procedencia, no una secuencia para apilar parches. Cada versión descargable tiene su propio delta directo desde la ROM limpia.':'Lineage describes provenance, not a patch-stacking recipe. Each downloadable build has its own direct delta from the clean ROM.'}</p><details class="feature-map-source"><summary>${es?'Ver fuente Mermaid':'View Mermaid source'}</summary><pre><code>${esc(source)}</code></pre></details></figure>`}
function featuresPage(){const es=state.lang==='es',guideData=state.data.guides?.features,body=document.createElement('div');if(!guideData)return missing();body.innerHTML=guideData.body?.[state.lang]||'';let intro='',groups=[],current=null;for(const node of [...body.children]){if(node.tagName==='P'&&!current&&!intro)intro=node.textContent;else if(node.tagName==='H3'){if(/^(credits|créditos)$/i.test(node.textContent.trim())){current=null;continue}current={title:node.textContent,content:[]};groups.push(current)}else if(current)current.content.push(node.outerHTML)}const groupHtml=groups.map((group,index)=>`<section class="feature-group"><p class="section-kicker">${String(index+1).padStart(2,'0')} / ${es?'CAPA':'LAYER'}</p><h2>${esc(group.title)}</h2>${group.content.join('')}</section>`).join('');return `<section class="features-page"><header class="features-page__header"><div><p class="eyebrow"><span class="eyebrow-mark" aria-hidden="true"></span>${es?'CARACTERÍSTICAS Y ESTADO':'FEATURES & BUILD STATUS'}</p><h1>${esc(text(guideData.title))}</h1><p class="features-page__intro">${esc(intro)}</p></div><a class="button button-primary features-page__cta" href="#/patcher">${es?'Elegir una versión':'Choose a build'} <span aria-hidden="true">↗</span></a></header>${featureComposition()}<div class="features-page__groups">${groupHtml||`<p class="notice">${L().noData}</p>`}</div><details class="feature-credits"><summary>${es?'Créditos y procedencia':'Credits and provenance'}</summary><div class="feature-credits__body">${es?'<p><a href="https://gbatemp.net/threads/pokemon-sacred-gold-storm-silver.327567/" target="_blank" rel="noopener">Drayano</a>: Sacred Gold / Storm Silver y Speed-Up oficial.</p><p><a href="https://github.com/Umberto-DEV/sacred-gold-plus" target="_blank" rel="noopener">Sacred Gold Plus</a>: creado originalmente por NefariousnessNo3436; la continuación 1.2.3 es de Umberto-DEV y colaboradores. La implementación Hada es de mikelan / Mikelan98.</p><p>Los parches propios de Ultimate Gold se mantienen en este proyecto. Los derechos del juego y los recursos de terceros pertenecen a sus titulares.</p>':'<p><a href="https://gbatemp.net/threads/pokemon-sacred-gold-storm-silver.327567/" target="_blank" rel="noopener">Drayano</a>: Sacred Gold / Storm Silver and official Speed-Up.</p><p><a href="https://github.com/Umberto-DEV/sacred-gold-plus" target="_blank" rel="noopener">Sacred Gold Plus</a>: originally created by NefariousnessNo3436; the 1.2.3 continuation is by Umberto-DEV and contributors. The Fairy implementation is by mikelan / Mikelan98.</p><p>Ultimate Gold’s custom patches are maintained in this project. Game and third-party asset rights remain with their respective owners.</p>'}</div></details></section>`}
function missing(){return `<h1>${L().notfound}</h1><p class="notice">${L().noData}</p>`}
function filterCards(input,selector){const q=$(input)?.value.toLowerCase()||'';document.querySelectorAll(selector).forEach(el=>{el.hidden=!!q&&!el.dataset.search.includes(q)})}
function wire(route){const search=$('search');const apply=()=>{const global=(search?.value||'').toLowerCase();if(route==='pokemon'&&$('dex-name')){const name=($('dex-name').value||'').toLowerCase(),gen=$('dex-gen')?.value||'',type=$('dex-type')?.value||'',statChange=$('dex-stat-change')?.value||'';document.querySelectorAll('.dex-card').forEach(c=>{c.hidden=!!((global&&!c.dataset.search.includes(global))||(name&&!c.dataset.search.includes(name))||(gen&&c.dataset.gen!==gen)||(type&&!c.dataset.types.split(',').includes(type))||(statChange&&c.dataset.statStatus!==statChange))})}else if(route==='trainers'){const qs=['trainer-filter','trainer-pokemon','trainer-move'].map(id=>($(id)?.value||'').toLowerCase()).filter(Boolean),loc=$('trainer-location')?.value||'';document.querySelectorAll('.location-group').forEach(g=>{g.hidden=!!(loc&&g.dataset.location!==loc)});document.querySelectorAll('.trainer-card').forEach(c=>{c.hidden=[global,...qs].filter(Boolean).some(x=>!c.dataset.search.includes(x))||!!(loc&&c.closest('.location-group')?.dataset.location!==loc)});document.querySelectorAll('.location-group').forEach(g=>{if(!g.hidden)g.hidden=[...g.querySelectorAll('.trainer-card')].every(c=>c.hidden)})}else if(route==='machines'){const q=[$('machine-filter')?.value||'',global].map(x=>x.toLowerCase()).filter(Boolean),kind=$('machine-kind')?.value||'',type=$('machine-type')?.value||'';document.querySelectorAll('.machine-row').forEach(c=>{c.hidden=q.some(x=>!c.dataset.search.includes(x))||!!(kind&&c.dataset.kind!==kind)||!!(type&&c.dataset.type!==type)})}else if(route==='moves'||route==='items'){const q=[global,$('move-filter')?.value||$('item-filter')?.value||''].map(x=>x.toLowerCase()).filter(Boolean),mt=$('move-type')?.value||'',mc=$('move-class')?.value||'',ic=$('item-category')?.value||'';document.querySelectorAll(route==='items'?'.item-row':'.move-card').forEach(c=>{c.hidden=q.some(x=>!c.dataset.search.includes(x))||!!(mt&&c.dataset.type!==mt)||!!(mc&&c.dataset.class!==mc)||!!(ic&&c.dataset.category!==ic)})}else if(route==='evolutions'){const q=[global,$('evolution-filter')?.value||''].map(x=>x.toLowerCase()).filter(Boolean);document.querySelectorAll('.evolution-family').forEach(c=>{c.hidden=q.some(value=>!c.dataset.search.includes(value))})}};['search','dex-name','dex-gen','dex-type','dex-stat-change','trainer-filter','trainer-pokemon','trainer-move','trainer-location','machine-filter','machine-kind','machine-type','move-filter','move-type','move-class','item-filter','item-category','evolution-filter'].forEach(id=>$(id)&&($(id).oninput=apply,$(id).onchange=apply));apply()}
function localizeChrome(){
  const labels=state.lang==='es'?{brandSubtitle:'Wiki del proyecto',fieldGuide:'Guía de campo',browse:'Explorar',credits:'Créditos',projectCredits:'Créditos del proyecto',brandHome:'Ultimate Gold Wiki · Inicio',wikiSections:'Secciones de la wiki',language:'Idioma'}:{brandSubtitle:'Project wiki',fieldGuide:'Field guide',browse:'Browse',credits:'Credits',projectCredits:'Project credits',brandHome:'Ultimate Gold Wiki · Home',wikiSections:'Wiki sections',language:'Language'};
  document.querySelectorAll('[data-ui-key]').forEach(node=>{if(labels[node.dataset.uiKey])node.textContent=labels[node.dataset.uiKey]});
  document.querySelectorAll('[data-ui-aria-key]').forEach(node=>{if(labels[node.dataset.uiAriaKey])node.setAttribute('aria-label',labels[node.dataset.uiAriaKey])});
  document.querySelectorAll('[data-ui-key="gameMode"]').forEach(node=>node.textContent=state.lang==='es'?'Modo de juego':'Game mode');
  const mode=$('game-mode');
  if(mode){mode.value=state.gameMode;mode.setAttribute('aria-label',state.lang==='es'?'Modo de juego':'Game mode');[...mode.options].forEach(option=>option.textContent=text(state.data.game_modes?.[option.value]?.name)||option.value)}
}
function changeGameMode(){
  const filters=Object.fromEntries(['trainer-kind','trainer-location','trainer-filter','trainer-pokemon','trainer-move'].filter(id=>$(id)).map(id=>[id,$(id).value]));
  const opened=[...document.querySelectorAll('.trainer-roster[open]')].map(node=>node.dataset.trainerId);
  state.gameMode=$('game-mode').value==='plus'?'plus':'normal';
  localStorage.setItem('ultimate-gold-game-mode',state.gameMode);
  render();
  if($('trainer-kind')){Object.entries(filters).forEach(([id,value])=>$(id).value=value);wireTrainerJourney();opened.forEach(id=>{const details=document.querySelector(`.trainer-roster[data-trainer-id="${id}"]`);if(details)details.open=true})}
}
window.addEventListener('message',event=>{
  const frame=$('patcher-frame');
  if(event.origin!==location.origin||event.source!==frame?.contentWindow||!event.data)return;
  if(event.data.type==='patcher-height'){
    const height=Number(event.data.height);
    if(Number.isFinite(height))frame.style.height=`${Math.max(420,Math.min(height,1800))}px`;
  }else if(event.data.type==='patcher-ready'){
    frame.contentWindow.postMessage({type:'wiki-language',language:state.lang},location.origin);
  }
});
function render(){
  if(!state.data)return;
  const parts=location.hash.replace(/^#\/?/,'').split('/'),route=parts[0]||'';
  document.title=state.lang==='es'?'Ultimate Gold · Wiki':'Ultimate Gold Wiki';
  localizeChrome();setNav(route);
  if(route==='cheats'){window.UltimateCheats.mount($('content'),state.lang,state.data.target_sha256);return}
  if(route==='patcher'){
    if(!$('patcher-frame'))$('content').innerHTML=patcher();
    localizePatcher();
    const frame=$('patcher-frame');
    document.title=state.lang==='es'?'Ultimate Gold · Wiki y parcheador':'Ultimate Gold · Wiki and patcher';
    if(frame.contentWindow)frame.contentWindow.postMessage({type:'wiki-language',language:state.lang},location.origin);
    return;
  }
  if(route==='faq'){
    $('content').innerHTML=faq();
    document.title=state.lang==='es'?'Ultimate Gold · Preguntas frecuentes':'Ultimate Gold · FAQ';
    return;
  }
  if(route==='kris-progress'){
    window.KrisProgress.mount($('content'),state.lang);
    document.title=state.lang==='es'?'Ultimate Gold · Progreso de Kris':'Ultimate Gold · Kris progress';
    return;
  }
  const id=parts[1];
  if(route==='guide'&&id==='features'){$('content').innerHTML=featuresPage();document.title=state.lang==='es'?'Ultimate Gold · Características':'Ultimate Gold · Features';return}
  $('content').innerHTML=route==='pokemon'?(id?pokemon(id):pokemonList()):route==='trainers'?trainersByLocation():route==='moves'?(id?move(id):movesList()):route==='items'?(id?item(id):itemsList()):route==='machines'?machines():route==='evolutions'?evolutions():route==='guide'?(id?guide(id):section('guides')):route==='guides'?guidesIndex():route==='mechanics'?section('mechanics'):home();
  if(route==='trainers')wireTrainerJourney();else wire(route);
}
async function init(){try{state.data=await fetch(DATA_URL).then(r=>r.ok?r.json():Promise.reject(new Error('wiki-data unavailable')));render()}catch(e){$('content').innerHTML=`<p class="notice">${esc(e.message)}</p>`}}
try{$('language').value=state.lang;$('language').onchange=()=>{state.lang=$('language').value==='es'?'es':'en';localStorage.setItem('sgp-language',state.lang);render()};if($('game-mode'))$('game-mode').onchange=changeGameMode;window.onhashchange=render;init()}catch(e){document.body.textContent='Wiki unavailable'}
